{"file_path": "scripts/migration/analyze-flows.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Flow Analysis Tool
 * 
 * Analyzes all existing Genkit flows and generates a comprehensive report
 * about their structure, complexity, and migration requirements.
 * 
 * Usage:
 *   npm run analyze-flows
 *   tsx scripts/migration/analyze-flows.ts
 */

import * as fs from 'fs';
import * as path from 'path';
import { FlowAnalyzer } from '@/lib/migration/analyzer/FlowAnalyzer';

interface FlowAnalysisReport {
  totalFlows: number;
  flowsByComplexity: {
    simple: string[];
    medium: string[];
    complex: string[];
  };
  flowsByCategory: Record<string, string[]>;
  migrationEstimate: {
    simple: number;    // hours
    medium: number;
    complex: number;
    total: number;
  };
  dependencies: {
    flowName: string;
    dependencies: string[];
  }[];
  warnings: string[];
}

async function analyzeFlows(): Promise<FlowAnalysisReport> {
  console.log('🔍 Starting flow analysis...\n');

  const flowsDir = path.join(process.cwd(), 'src/ai/flows');
  const flowFiles = fs.readdirSync(flowsDir)
    .filter(file => file.endsWith('.ts') && file !== 'index.ts');

  const analyzer = new FlowAnalyzer();
  const report: FlowAnalysisReport = {
    totalFlows: 0,
    flowsByComplexity: {
      simple: [],
      medium: [],
      complex: [],
    },
    flowsByCategory: {},
    migrationEstimate: {
      simple: 0,
      medium: 0,
      complex: 0,
      total: 0,
    },
    dependencies: [],
    warnings: [],
  };

  for (const file of flowFiles) {
    const flowPath = path.join(flowsDir, file);
    const flowName = file.replace('.ts', '');

    console.log(`📄 Analyzing: ${flowName}`);

    try {
      const analysis = await analyzer.analyzeFlow(flowPath);
      report.totalFlows++;

      // Categorize by complexity
      const complexity = analysis.complexity || 'medium';
      report.flowsByComplexity[complexity as keyof typeof report.flowsByComplexity].push(flowName);

      // Categorize by type
      const category = analysis.category || 'general';
      if (!report.flowsByCategory[category]) {
        report.flowsByCategory[category] = [];
      }
      report.flowsByCategory[category].push(flowName);

      // Track dependencies
      if (analysis.dependencies && analysis.dependencies.length > 0) {
        report.dependencies.push({
          flowName,
          dependencies: analysis.dependencies,
        });
      }

      // Collect warnings
      if (analysis.warnings) {
        report.warnings.push(...analysis.warnings.map(w => `${flowName}: ${w}`));
      }

      // Estimate migration time
      const estimateHours = {
        simple: 2,
        medium: 4,
        complex: 8,
      };
      report.migrationEstimate[complexity as keyof typeof estimateHours] += 
        estimateHours[complexity as keyof typeof estimateHours] || 4;

    } catch (error) {
      console.error(`❌ Error analyzing ${flowName}:`, error);
      report.warnings.push(`${flowName}: Failed to analyze - ${error}`);
    }
  }

  // Calculate totals
  report.migrationEstimate.total = 
    report.migrationEstimate.simple + 
    report.migrationEstimate.medium + 
    report.migrationEstimate.complex;

  return report;
}

function printReport(report: FlowAnalysisReport): void {
  console.log('\n' + '='.repeat(80));
  console.log('📊 FLOW ANALYSIS REPORT');
  console.log('='.repeat(80) + '\n');

  console.log(`Total Flows: ${report.totalFlows}\n`);

  console.log('Complexity Breakdown:');
  console.log(`  Simple (${report.flowsByComplexity.simple.length}): ${report.flowsByComplexity.simple.join(', ')}`);
  console.log(`  Medium (${report.flowsByComplexity.medium.length}): ${report.flowsByComplexity.medium.join(', ')}`);
  console.log(`  Complex (${report.flowsByComplexity.complex.length}): ${report.flowsByComplexity.complex.join(', ')}\n`);

  console.log('Category Breakdown:');
  Object.entries(report.flowsByCategory).forEach(([category, flows]) => {
    console.log(`  ${category} (${flows.length}): ${flows.join(', ')}`);
  });

  console.log('\nMigration Time Estimate:');
  console.log(`  Simple flows: ${report.migrationEstimate.simple} hours`);
  console.log(`  Medium flows: ${report.migrationEstimate.medium} hours`);
  console.log(`  Complex flows: ${report.migrationEstimate.complex} hours`);
  console.log(`  Total: ${report.migrationEstimate.total} hours (${(report.migrationEstimate.total / 8).toFixed(1)} days)\n`);

  if (report.dependencies.length > 0) {
    console.log('Flow Dependencies:');
    report.dependencies.forEach(({ flowName, dependencies }) => {
      console.log(`  ${flowName} → ${dependencies.join(', ')}`);
    });
    console.log('');
  }

  if (report.warnings.length > 0) {
    console.log('⚠️  Warnings:');
    report.warnings.forEach(warning => {
      console.log(`  - ${warning}`);
    });
    console.log('');
  }

  console.log('='.repeat(80) + '\n');
}

function saveReport(report: FlowAnalysisReport): void {
  const outputPath = path.join(process.cwd(), 'migration-analysis-report.json');
  fs.writeFileSync(outputPath, JSON.stringify(report, null, 2));
  console.log(`💾 Report saved to: ${outputPath}\n`);
}

// Main execution
async function main() {
  try {
    const report = await analyzeFlows();
    printReport(report);
    saveReport(report);

    console.log('✅ Analysis complete!\n');
    process.exit(0);
  } catch (error) {
    console.error('❌ Analysis failed:', error);
    process.exit(1);
  }
}

main();
"}

{"file_path": "scripts/migration/extract-prompts.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Prompt Extraction Script
 * 
 * Extracts prompts from existing Genkit flows and creates
 * reusable prompt configurations in the database.
 * 
 * Usage:
 *   npm run extract-prompts
 *   tsx scripts/migration/extract-prompts.ts [flowName]
 */

import * as fs from 'fs';
import * as path from 'path';
import * as ts from 'typescript';
import { initializeApp } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';
import type { PromptConfig } from '@/lib/models/prompt-config';

// Initialize Firebase
try {
  initializeApp();
} catch (error) {
  // Already initialized
}

const db = getFirestore();

interface ExtractedPrompt {
  flowName: string;
  promptText: string;
  variables: string[];
  context: string;
  lineNumber: number;
}

/**
 * Extract prompts from a TypeScript source file
 */
function extractPromptsFromFile(filePath: string): ExtractedPrompt[] {
  const sourceCode = fs.readFileSync(filePath, 'utf-8');
  const sourceFile = ts.createSourceFile(
    filePath,
    sourceCode,
    ts.ScriptTarget.Latest,
    true
  );

  const prompts: ExtractedPrompt[] = [];
  const flowName = path.basename(filePath, '.ts');

  function visit(node: ts.Node) {
    // Look for template literals or string literals that look like prompts
    if (ts.isTemplateExpression(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
      const text = node.getText(sourceFile);

      // Check if this looks like a prompt (contains certain keywords)
      if (
        text.length > 100 && // Prompts are usually long
        (text.includes('Generate') || 
         text.includes('Analyze') || 
         text.includes('Write') ||
         text.includes('Create') ||
         text.includes('You are'))
      ) {
        // Extract variables from template expressions
        const variables: string[] = [];
        const variableRegex = /\$\{([^}]+)\}/g;
        let match;

        while ((match = variableRegex.exec(text)) !== null) {
          const variable = match[1].trim();
          if (!variables.includes(variable)) {
            variables.push(variable);
          }
        }

        // Get context (parent function or arrow function)
        let context = 'unknown';
        let parent = node.parent;
        while (parent) {
          if (ts.isFunctionDeclaration(parent) || ts.isArrowFunction(parent)) {
            const functionName = ts.isFunctionDeclaration(parent) && parent.name
              ? parent.name.getText(sourceFile)
              : 'anonymous';
            context = functionName;
            break;
          }
          parent = parent.parent;
        }

        const lineNumber = sourceFile.getLineAndCharacterOfPosition(node.getStart()).line + 1;

        prompts.push({
          flowName,
          promptText: text.replace(/`/g, '').trim(),
          variables,
          context,
          lineNumber,
        });
      }
    }

    ts.forEachChild(node, visit);
  }

  visit(sourceFile);
  return prompts;
}

/**
 * Create a prompt configuration from extracted prompt
 */
function createPromptConfig(extracted: ExtractedPrompt): Omit<PromptConfig, 'id' | 'createdAt' | 'updatedAt'> {
  const name = `${extracted.flowName}_${extracted.context}`.replace(/[^a-zA-Z0-9_]/g, '_');

  // Extract variable definitions from the prompt text
  const variableDefinitions: Record<string, { type: string; description: string; required: boolean }> = {};

  extracted.variables.forEach(variable => {
    // Try to infer type from variable name
    let type = 'string';
    const varLower = variable.toLowerCase();

    if (varLower.includes('count') || varLower.includes('number') || varLower.includes('limit')) {
      type = 'number';
    } else if (varLower.includes('enable') || varLower.includes('is') || varLower.includes('has')) {
      type = 'boolean';
    } else if (varLower.includes('list') || varLower.includes('items') || varLower.includes('array')) {
      type = 'array';
    }

    variableDefinitions[variable] = {
      type,
      description: `Variable from ${extracted.flowName}`,
      required: true,
    };
  });

  return {
    name,
    description: `Extracted from ${extracted.flowName} at line ${extracted.lineNumber}`,
    template: extracted.promptText,
    variables: variableDefinitions,
    category: 'extracted',
    tags: [extracted.flowName, 'migration', 'extracted'],
    version: 1,
    isActive: true,
    model: 'gemini-2.0-flash-exp',
    temperature: 0.7,
    maxTokens: 2048,
  };
}

/**
 * Save prompt to Firestore
 */
async function savePromptToFirestore(promptConfig: Omit<PromptConfig, 'id' | 'createdAt' | 'updatedAt'>): Promise<string> {
  const docRef = await db.collection('prompts').add({
    ...promptConfig,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });

  return docRef.id;
}

/**
 * Extract prompts from a single flow file
 */
async function extractPromptsFromFlow(flowName: string): Promise<number> {
  const flowPath = path.join(process.cwd(), 'src/ai/flows', `${flowName}.ts`);

  if (!fs.existsSync(flowPath)) {
    throw new Error(`Flow file not found: ${flowPath}`);
  }

  console.log(`🔍 Extracting prompts from: ${flowName}`);

  const extractedPrompts = extractPromptsFromFile(flowPath);

  if (extractedPrompts.length === 0) {
    console.log(`  ℹ️  No prompts found`);
    return 0;
  }

  console.log(`  📝 Found ${extractedPrompts.length} prompt(s)`);

  let savedCount = 0;
  for (const extracted of extractedPrompts) {
    const promptConfig = createPromptConfig(extracted);

    try {
      const promptId = await savePromptToFirestore(promptConfig);
      console.log(`  ✅ Saved prompt: ${promptConfig.name} (ID: ${promptId})`);
      savedCount++;
    } catch (error) {
      console.error(`  ❌ Failed to save prompt ${promptConfig.name}:`, error);
    }
  }

  return savedCount;
}

/**
 * Extract prompts from all flows
 */
async function extractAllPrompts(): Promise<void> {
  const flowsDir = path.join(process.cwd(), 'src/ai/flows');
  const flowFiles = fs.readdirSync(flowsDir)
    .filter(file => file.endsWith('.ts') && file !== 'index.ts');

  console.log(`📦 Extracting prompts from ${flowFiles.length} flows...\n`);

  let totalPrompts = 0;
  for (const file of flowFiles) {
    const flowName = file.replace('.ts', '');
    try {
      const count = await extractPromptsFromFlow(flowName);
      totalPrompts += count;
    } catch (error) {
      console.error(`❌ Error processing ${flowName}:`, error);
    }
    console.log('');
  }

  console.log(`\n✅ Extraction complete! Total prompts saved: ${totalPrompts}`);
}

// Main execution
async function main() {
  const flowName = process.argv[2];

  try {
    if (flowName) {
      // Extract from specific flow
      const count = await extractPromptsFromFlow(flowName);
      console.log(`\n✅ Extracted ${count} prompt(s) from ${flowName}`);
    } else {
      // Extract from all flows
      await extractAllPrompts();
    }

    process.exit(0);
  } catch (error) {
    console.error('❌ Extraction failed:', error);
    process.exit(1);
  }
}

main();
"}

{"file_path": "scripts/migration/create-flow-configs.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Flow Configuration Generator
 * 
 * Generates dynamic flow configurations from existing static Genkit flows.
 * Uses the ConfigurationGenerator to create database-ready flow configs.
 * 
 * Usage:
 *   npm run create-flow-configs
 *   tsx scripts/migration/create-flow-configs.ts [flowName]
 */

import * as fs from 'fs';
import * as path from 'path';
import { initializeApp } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';
import { ConfigurationGenerator } from '@/lib/migration/generator/ConfigurationGenerator';
import type { FlowConfig } from '@/lib/models/flow-config';

// Initialize Firebase
try {
  initializeApp();
} catch (error) {
  // Already initialized
}

const db = getFirestore();

/**
 * Save flow configuration to Firestore
 */
async function saveFlowConfig(flowConfig: Omit<FlowConfig, 'id' | 'createdAt' | 'updatedAt'>): Promise<string> {
  const docRef = await db.collection('flowConfigs').add({
    ...flowConfig,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });

  console.log(`  💾 Saved to Firestore with ID: ${docRef.id}`);
  return docRef.id;
}

/**
 * Generate and save flow configuration for a single flow
 */
async function generateFlowConfig(flowName: string, saveToDB: boolean = true): Promise<FlowConfig | null> {
  const flowPath = path.join(process.cwd(), 'src/ai/flows', `${flowName}.ts`);

  if (!fs.existsSync(flowPath)) {
    throw new Error(`Flow file not found: ${flowPath}`);
  }

  console.log(`\n🔧 Generating configuration for: ${flowName}`);
  console.log(`  📄 Source: ${flowPath}`);

  const generator = new ConfigurationGenerator();

  try {
    const flowConfig = await generator.generateFlowConfig(flowPath);

    console.log(`  ✅ Configuration generated successfully`);
    console.log(`  📊 Steps: ${flowConfig.steps.length}`);
    console.log(`  🏷️  Category: ${flowConfig.category}`);
    console.log(`  🏷️  Tags: ${flowConfig.tags.join(', ')}`);

    // Save to JSON file for review
    const outputDir = path.join(process.cwd(), 'migration-configs');
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    const outputPath = path.join(outputDir, `${flowName}.json`);
    fs.writeFileSync(outputPath, JSON.stringify(flowConfig, null, 2));
    console.log(`  📝 Config saved to: ${outputPath}`);

    // Save to database if requested
    if (saveToDB) {
      const docId = await saveFlowConfig(flowConfig);
      return { ...flowConfig, id: docId } as FlowConfig;
    }

    return flowConfig as FlowConfig;
  } catch (error) {
    console.error(`  ❌ Failed to generate configuration:`, error);
    throw error;
  }
}

/**
 * Generate configurations for all flows
 */
async function generateAllFlowConfigs(saveToDB: boolean = true): Promise<void> {
  const flowsDir = path.join(process.cwd(), 'src/ai/flows');
  const flowFiles = fs.readdirSync(flowsDir)
    .filter(file => file.endsWith('.ts') && file !== 'index.ts');

  console.log(`🚀 Generating configurations for ${flowFiles.length} flows...\n`);
  console.log(`Database save: ${saveToDB ? 'ENABLED' : 'DISABLED'}\n`);

  const results = {
    success: [] as string[],
    failed: [] as string[],
  };

  for (const file of flowFiles) {
    const flowName = file.replace('.ts', '');

    try {
      await generateFlowConfig(flowName, saveToDB);
      results.success.push(flowName);
    } catch (error) {
      console.error(`\n❌ Failed to process ${flowName}:`, error);
      results.failed.push(flowName);
    }
  }

  // Print summary
  console.log('\n' + '='.repeat(80));
  console.log('📊 GENERATION SUMMARY');
  console.log('='.repeat(80));
  console.log(`\nSuccessful: ${results.success.length}/${flowFiles.length}`);
  if (results.success.length > 0) {
    console.log(`  ✅ ${results.success.join(', ')}`);
  }

  if (results.failed.length > 0) {
    console.log(`\nFailed: ${results.failed.length}/${flowFiles.length}`);
    console.log(`  ❌ ${results.failed.join(', ')}`);
  }

  console.log('\n' + '='.repeat(80) + '\n');

  // Save summary
  const summaryPath = path.join(process.cwd(), 'migration-configs', 'summary.json');
  fs.writeFileSync(summaryPath, JSON.stringify(results, null, 2));
  console.log(`📄 Summary saved to: ${summaryPath}\n`);
}

// Main execution
async function main() {
  const args = process.argv.slice(2);
  const flowName = args.find(arg => !arg.startsWith('--'));
  const dryRun = args.includes('--dry-run');
  const saveToDB = !dryRun;

  console.log('🔧 Flow Configuration Generator\n');

  if (dryRun) {
    console.log('⚠️  DRY RUN MODE - configurations will NOT be saved to database\n');
  }

  try {
    if (flowName) {
      // Generate specific flow
      await generateFlowConfig(flowName, saveToDB);
      console.log('\n✅ Configuration generation complete!');
    } else {
      // Generate all flows
      await generateAllFlowConfigs(saveToDB);
      console.log('✅ All configurations generated!');
    }

    process.exit(0);
  } catch (error) {
    console.error('\n❌ Generation failed:', error);
    process.exit(1);
  }
}

main();
"}

{"file_path": "scripts/migration/migrate-flows.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Flow Migration Script
 * 
 * Orchestrates the complete migration of flows from static to dynamic.
 * Runs analysis, extraction, generation, and validation in sequence.
 * 
 * Usage:
 *   npm run migrate-flows
 *   tsx scripts/migration/migrate-flows.ts [--phase=1] [--flows=flow1,flow2]
 */

import * as fs from 'fs';
import * as path from 'path';
import { FlowAnalyzer } from '@/lib/migration/analyzer/FlowAnalyzer';
import { ConfigurationGenerator } from '@/lib/migration/generator/ConfigurationGenerator';
import { MigrationValidator } from '@/lib/migration/validator/MigrationValidator';
import { initializeApp } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';

// Initialize Firebase
try {
  initializeApp();
} catch (error) {
  // Already initialized
}

const db = getFirestore();

interface MigrationPhase {
  phase: number;
  name: string;
  flows: string[];
  description: string;
}

const MIGRATION_PHASES: MigrationPhase[] = [
  {
    phase: 1,
    name: 'Simple Text Generation',
    description: 'Basic text generation and manipulation flows',
    flows: [
      'generate-text',
      'paraphrase-text',
      'summarize-text',
      'translate-text',
      'humanize-text',
      'manipulate-text',
      'text-stylist',
      'improve-report-markdown',
      'rewrite-to-markdown',
      'rewrite-document-to-markdown',
      'generate-ideas',
      'topic-explainer',
      'generate-toc',
      'generate-citation',
      'generate-ui-description',
    ],
  },
  {
    phase: 2,
    name: 'Analysis Tools',
    description: 'Document analysis and checking flows',
    flows: [
      'grammar-checker',
      'bias-checker',
      'fact-checker',
      'plagiarism-checker',
      'detect-ai-content',
      'sentence-structure-checker',
      'question-answering',
      'analyze-context',
    ],
  },
  {
    phase: 3,
    name: 'Complex Document Generation',
    description: 'Multi-step document and report generation',
    flows: [
      'generate-report-section',
      'generate-chapter-content',
      'write-document',
      'professional-document-writer',
      'generate-quiz',
      'generate-session-plan',
      'create-lecture-unit',
      'generate-theoretical-lecture',
      'presentation-content-creator',
      'technical-spec-writer',
      'project-documentation-generator',
      'solve-assignments',
      'generate-diagrams',
      'generate-plantuml',
    ],
  },
  {
    phase: 4,
    name: 'Academic & Research',
    description: 'Academic writing and research flows with heavy RAG',
    flows: [
      'academic-literature-review',
      'ai-researcher',
      'graduation-project-generator',
      'literature-review-generator',
      'academic-paper-quality-checker',
      'ai-proofread-document',
      'fact-retrieval',
      'project-report-generator',
      'generate-project-blueprint',
    ],
  },
  {
    phase: 5,
    name: 'Special & RAG-Enhanced',
    description: 'Flows with RAG integration and special requirements',
    flows: [
      'generate-report-section-rag',
      'generate-chapter-content-rag',
      'summarize-document',
      'image-to-text',
      'text-to-speech',
      'generate-image',
      'run-agent-flow',
      'dynamic-flow-executor',
    ],
  },
];

interface MigrationResult {
  flowName: string;
  success: boolean;
  configId?: string;
  error?: string;
  validationResults?: any;
  duration: number;
}

interface MigrationReport {
  phase: number;
  startTime: string;
  endTime?: string;
  totalFlows: number;
  successful: number;
  failed: number;
  results: MigrationResult[];
}

/**
 * Migrate a single flow
 */
async function migrateFlow(flowName: string): Promise<MigrationResult> {
  const startTime = Date.now();
  console.log(`\n${'='.repeat(80)}`);
  console.log(`🔄 Migrating: ${flowName}`);
  console.log('='.repeat(80));

  try {
    const flowPath = path.join(process.cwd(), 'src/ai/flows', `${flowName}.ts`);

    if (!fs.existsSync(flowPath)) {
      throw new Error(`Flow file not found: ${flowPath}`);
    }

    // Step 1: Analyze the flow
    console.log('\n📊 Step 1: Analyzing flow...');
    const analyzer = new FlowAnalyzer();
    const analysis = await analyzer.analyzeFlow(flowPath);
    console.log(`  ✅ Complexity: ${analysis.complexity}`);
    console.log(`  ✅ Category: ${analysis.category}`);

    if (analysis.warnings && analysis.warnings.length > 0) {
      console.log(`  ⚠️  Warnings: ${analysis.warnings.length}`);
      analysis.warnings.forEach(w => console.log(`     - ${w}`));
    }

    // Step 2: Generate configuration
    console.log('\n🔧 Step 2: Generating configuration...');
    const generator = new ConfigurationGenerator();
    const flowConfig = await generator.generateFlowConfig(flowPath);
    console.log(`  ✅ Generated ${flowConfig.steps.length} steps`);

    // Step 3: Validate configuration
    console.log('\n✅ Step 3: Validating configuration...');
    const validator = new MigrationValidator();
    const validationResults = await validator.validateFlowConfig(flowConfig);

    if (!validationResults.valid) {
      console.log(`  ❌ Validation failed:`);
      validationResults.errors?.forEach(e => console.log(`     - ${e}`));
      throw new Error('Configuration validation failed');
    }
    console.log('  ✅ Configuration is valid');

    // Step 4: Save to database
    console.log('\n💾 Step 4: Saving to database...');
    const docRef = await db.collection('flowConfigs').add({
      ...flowConfig,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      migrationDate: new Date().toISOString(),
      sourceFile: flowPath,
    });
    console.log(`  ✅ Saved with ID: ${docRef.id}`);

    // Step 5: Save backup
    const backupDir = path.join(process.cwd(), 'migration-backups');
    if (!fs.existsSync(backupDir)) {
      fs.mkdirSync(backupDir, { recursive: true });
    }

    const backupPath = path.join(backupDir, `${flowName}_${Date.now()}.json`);
    fs.writeFileSync(backupPath, JSON.stringify(flowConfig, null, 2));
    console.log(`  💾 Backup saved: ${backupPath}`);

    const duration = Date.now() - startTime;
    console.log(`\n✅ Migration successful! (${duration}ms)`);

    return {
      flowName,
      success: true,
      configId: docRef.id,
      validationResults,
      duration,
    };

  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`\n❌ Migration failed:`, error);

    return {
      flowName,
      success: false,
      error: error instanceof Error ? error.message : String(error),
      duration,
    };
  }
}

/**
 * Migrate flows for a specific phase
 */
async function migratePhase(phase: MigrationPhase): Promise<MigrationReport> {
  console.log('\n' + '█'.repeat(80));
  console.log(`🚀 PHASE ${phase.phase}: ${phase.name}`);
  console.log(`📝 ${phase.description}`);
  console.log(`📊 Flows to migrate: ${phase.flows.length}`);
  console.log('█'.repeat(80) + '\n');

  const report: MigrationReport = {
    phase: phase.phase,
    startTime: new Date().toISOString(),
    totalFlows: phase.flows.length,
    successful: 0,
    failed: 0,
    results: [],
  };

  for (const flowName of phase.flows) {
    const result = await migrateFlow(flowName);
    report.results.push(result);

    if (result.success) {
      report.successful++;
    } else {
      report.failed++;
    }

    // Small delay between migrations
    await new Promise(resolve => setTimeout(resolve, 1000));
  }

  report.endTime = new Date().toISOString();

  // Print phase summary
  console.log('\n' + '='.repeat(80));
  console.log(`📊 PHASE ${phase.phase} SUMMARY`);
  console.log('='.repeat(80));
  console.log(`Total: ${report.totalFlows}`);
  console.log(`✅ Successful: ${report.successful}`);
  console.log(`❌ Failed: ${report.failed}`);
  console.log(`📈 Success Rate: ${((report.successful / report.totalFlows) * 100).toFixed(1)}%`);

  if (report.failed > 0) {
    console.log('\nFailed flows:');
    report.results
      .filter(r => !r.success)
      .forEach(r => console.log(`  ❌ ${r.flowName}: ${r.error}`));
  }

  console.log('='.repeat(80) + '\n');

  // Save phase report
  const reportPath = path.join(
    process.cwd(), 
    'migration-reports', 
    `phase-${phase.phase}-report.json`
  );
  const reportDir = path.dirname(reportPath);
  if (!fs.existsSync(reportDir)) {
    fs.mkdirSync(reportDir, { recursive: true });
  }
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
  console.log(`📄 Phase report saved: ${reportPath}\n`);

  return report;
}

/**
 * Main migration function
 */
async function main() {
  const args = process.argv.slice(2);

  // Parse arguments
  const phaseArg = args.find(arg => arg.startsWith('--phase='));
  const flowsArg = args.find(arg => arg.startsWith('--flows='));

  const targetPhase = phaseArg ? parseInt(phaseArg.split('=')[1]) : null;
  const specificFlows = flowsArg ? flowsArg.split('=')[1].split(',') : null;

  console.log('🚀 Flow Migration Tool\n');

  try {
    if (specificFlows) {
      // Migrate specific flows
      console.log(`📋 Migrating specific flows: ${specificFlows.join(', ')}\n`);

      for (const flowName of specificFlows) {
        await migrateFlow(flowName.trim());
      }

      console.log('\n✅ Migration complete!');

    } else if (targetPhase) {
      // Migrate specific phase
      const phase = MIGRATION_PHASES.find(p => p.phase === targetPhase);

      if (!phase) {
        throw new Error(`Invalid phase: ${targetPhase}`);
      }

      await migratePhase(phase);
      console.log('✅ Phase migration complete!');

    } else {
      // Migrate all phases
      console.log('🌟 Starting full migration (all phases)\n');

      const allReports: MigrationReport[] = [];

      for (const phase of MIGRATION_PHASES) {
        const report = await migratePhase(phase);
        allReports.push(report);

        // Pause between phases
        console.log('⏸️  Pausing 5 seconds before next phase...\n');
        await new Promise(resolve => setTimeout(resolve, 5000));
      }

      // Print final summary
      const totalFlows = allReports.reduce((sum, r) => sum + r.totalFlows, 0);
      const totalSuccessful = allReports.reduce((sum, r) => sum + r.successful, 0);
      const totalFailed = allReports.reduce((sum, r) => sum + r.failed, 0);

      console.log('\n' + '█'.repeat(80));
      console.log('🎉 MIGRATION COMPLETE - FINAL SUMMARY');
      console.log('█'.repeat(80));
      console.log(`\nTotal Flows: ${totalFlows}`);
      console.log(`✅ Successful: ${totalSuccessful}`);
      console.log(`❌ Failed: ${totalFailed}`);
      console.log(`📈 Overall Success Rate: ${((totalSuccessful / totalFlows) * 100).toFixed(1)}%`);
      console.log('\n' + '█'.repeat(80) + '\n');

      // Save final summary
      const summaryPath = path.join(process.cwd(), 'migration-reports', 'final-summary.json');
      fs.writeFileSync(summaryPath, JSON.stringify({
        completedAt: new Date().toISOString(),
        totalFlows,
        totalSuccessful,
        totalFailed,
        successRate: (totalSuccessful / totalFlows) * 100,
        phases: allReports,
      }, null, 2));
      console.log(`📄 Final summary saved: ${summaryPath}\n`);
    }

    process.exit(0);

  } catch (error) {
    console.error('\n❌ Migration failed:', error);
    process.exit(1);
  }
}

main();
"}

{"file_path": "scripts/migration/compare-outputs.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Output Comparison Tool
 * 
 * Compares outputs from static flows vs dynamic flows to ensure
 * migration accuracy and quality.
 * 
 * Usage:
 *   npm run compare-outputs
 *   tsx scripts/migration/compare-outputs.ts <flowName> [--runs=5]
 */

import * as fs from 'fs';
import * as path from 'path';
import { ai } from '@/ai/genkit';
import { ComparisonTools } from '@/lib/migration/ComparisonTools';

interface ComparisonResult {
  flowName: string;
  testCase: number;
  input: any;
  staticOutput: any;
  dynamicOutput: any;
  similarity: number;
  identical: boolean;
  differences: string[];
  executionTime: {
    static: number;
    dynamic: number;
  };
}

interface ComparisonReport {
  flowName: string;
  timestamp: string;
  totalTests: number;
  identicalOutputs: number;
  averageSimilarity: number;
  averageExecutionTime: {
    static: number;
    dynamic: number;
    percentDifference: number;
  };
  results: ComparisonResult[];
  recommendation: 'PASS' | 'REVIEW' | 'FAIL';
  notes: string[];
}

/**
 * Generate test inputs for a flow
 */
function generateTestInputs(flowName: string): any[] {
  // Define test cases for different flow types
  const testCases: Record<string, any[]> = {
    'generate-text': [
      { prompt: 'Write a short story about AI', language: 'en', tone: 'creative' },
      { prompt: 'Explain quantum computing', language: 'en', tone: 'educational' },
      { prompt: 'Write a product description', language: 'en', tone: 'professional' },
    ],
    'paraphrase-text': [
      { text: 'The quick brown fox jumps over the lazy dog.', style: 'formal' },
      { text: 'Artificial intelligence is transforming technology.', style: 'simple' },
      { text: 'Climate change requires immediate action.', style: 'academic' },
    ],
    'summarize-text': [
      { text: 'Long article about machine learning...', maxLength: 100 },
      { text: 'Research paper on neural networks...', maxLength: 200 },
    ],
    'translate-text': [
      { text: 'Hello, how are you?', targetLanguage: 'es' },
      { text: 'Artificial intelligence', targetLanguage: 'fr' },
      { text: 'Good morning', targetLanguage: 'ar' },
    ],
  };

  return testCases[flowName] || [
    { input: 'test input 1' },
    { input: 'test input 2' },
    { input: 'test input 3' },
  ];
}

/**
 * Execute static flow
 */
async function executeStaticFlow(flowName: string, input: any): Promise<{ output: any; duration: number }> {
  const startTime = Date.now();

  try {
    // Import the static flow
    const flowModule = await import(`@/ai/flows/${flowName}`);
    const flowFunction = Object.values(flowModule)[0] as any;

    // Execute the flow
    const output = await flowFunction(input);
    const duration = Date.now() - startTime;

    return { output, duration };
  } catch (error) {
    console.error(`Error executing static flow:`, error);
    throw error;
  }
}

/**
 * Execute dynamic flow
 */
async function executeDynamicFlow(flowName: string, input: any): Promise<{ output: any; duration: number }> {
  const startTime = Date.now();

  try {
    // Execute via dynamic flow executor
    const { executeDynamicFlow } = await import('@/ai/flows/dynamic-flow-executor');
    const output = await executeDynamicFlow(flowName, input);
    const duration = Date.now() - startTime;

    return { output, duration };
  } catch (error) {
    console.error(`Error executing dynamic flow:`, error);
    throw error;
  }
}

/**
 * Compare two outputs
 */
function compareOutputs(output1: any, output2: any): {
  similarity: number;
  identical: boolean;
  differences: string[];
} {
  const tools = new ComparisonTools();

  // Use ComparisonTools to calculate similarity
  const similarity = tools.calculateSimilarity(output1, output2);

  // Check if identical (within tolerance)
  const identical = similarity >= 0.95;

  // Find differences
  const differences: string[] = [];

  if (typeof output1 === 'object' && typeof output2 === 'object') {
    const keys1 = Object.keys(output1);
    const keys2 = Object.keys(output2);

    // Check for missing keys
    keys1.forEach(key => {
      if (!keys2.includes(key)) {
        differences.push(`Missing key in dynamic output: ${key}`);
      }
    });

    keys2.forEach(key => {
      if (!keys1.includes(key)) {
        differences.push(`Extra key in dynamic output: ${key}`);
      }
    });

    // Check for different values
    keys1.forEach(key => {
      if (keys2.includes(key) && output1[key] !== output2[key]) {
        differences.push(`Different value for ${key}`);
      }
    });
  } else if (output1 !== output2) {
    differences.push('Outputs are not identical');
  }

  return { similarity, identical, differences };
}

/**
 * Run comparison for a flow
 */
async function compareFlow(flowName: string, numRuns: number = 3): Promise<ComparisonReport> {
  console.log(`\n${'='.repeat(80)}`);
  console.log(`🔍 Comparing: ${flowName}`);
  console.log('='.repeat(80));

  const testInputs = generateTestInputs(flowName);
  const results: ComparisonResult[] = [];

  console.log(`\n📋 Running ${testInputs.length} test cases (${numRuns} runs each)...\n`);

  let testCaseNumber = 0;
  for (const input of testInputs) {
    testCaseNumber++;
    console.log(`\n📝 Test Case ${testCaseNumber}:`);
    console.log(`  Input: ${JSON.stringify(input).substring(0, 100)}...`);

    for (let run = 1; run <= numRuns; run++) {
      console.log(`\n  Run ${run}/${numRuns}:`);

      try {
        // Execute static flow
        console.log('    ⚙️  Executing static flow...');
        const staticResult = await executeStaticFlow(flowName, input);
        console.log(`    ✅ Static: ${staticResult.duration}ms`);

        // Execute dynamic flow
        console.log('    ⚙️  Executing dynamic flow...');
        const dynamicResult = await executeDynamicFlow(flowName, input);
        console.log(`    ✅ Dynamic: ${dynamicResult.duration}ms`);

        // Compare outputs
        const comparison = compareOutputs(staticResult.output, dynamicResult.output);

        console.log(`    📊 Similarity: ${(comparison.similarity * 100).toFixed(1)}%`);
        if (comparison.identical) {
          console.log('    ✅ Outputs are identical!');
        } else {
          console.log(`    ⚠️  ${comparison.differences.length} difference(s) found`);
        }

        results.push({
          flowName,
          testCase: testCaseNumber,
          input,
          staticOutput: staticResult.output,
          dynamicOutput: dynamicResult.output,
          similarity: comparison.similarity,
          identical: comparison.identical,
          differences: comparison.differences,
          executionTime: {
            static: staticResult.duration,
            dynamic: dynamicResult.duration,
          },
        });

      } catch (error) {
        console.error(`    ❌ Error:`, error);
      }
    }
  }

  // Calculate summary statistics
  const identicalOutputs = results.filter(r => r.identical).length;
  const averageSimilarity = results.reduce((sum, r) => sum + r.similarity, 0) / results.length;

  const avgStaticTime = results.reduce((sum, r) => sum + r.executionTime.static, 0) / results.length;
  const avgDynamicTime = results.reduce((sum, r) => sum + r.executionTime.dynamic, 0) / results.length;
  const percentDifference = ((avgDynamicTime - avgStaticTime) / avgStaticTime) * 100;

  // Determine recommendation
  let recommendation: 'PASS' | 'REVIEW' | 'FAIL' = 'PASS';
  const notes: string[] = [];

  if (averageSimilarity < 0.8) {
    recommendation = 'FAIL';
    notes.push('Low similarity score - significant differences detected');
  } else if (averageSimilarity < 0.9) {
    recommendation = 'REVIEW';
    notes.push('Moderate similarity - manual review recommended');
  }

  if (percentDifference > 50) {
    if (recommendation === 'PASS') recommendation = 'REVIEW';
    notes.push('Dynamic flow is significantly slower (>50%)');
  } else if (percentDifference > 20) {
    notes.push('Dynamic flow is moderately slower (>20%)');
  } else if (percentDifference < -20) {
    notes.push('Dynamic flow is faster than static flow');
  }

  if (identicalOutputs === results.length) {
    notes.push('All outputs are identical - excellent migration!');
  }

  const report: ComparisonReport = {
    flowName,
    timestamp: new Date().toISOString(),
    totalTests: results.length,
    identicalOutputs,
    averageSimilarity,
    averageExecutionTime: {
      static: avgStaticTime,
      dynamic: avgDynamicTime,
      percentDifference,
    },
    results,
    recommendation,
    notes,
  };

  // Print summary
  console.log('\n' + '='.repeat(80));
  console.log('📊 COMPARISON SUMMARY');
  console.log('='.repeat(80));
  console.log(`\nTests Run: ${results.length}`);
  console.log(`Identical Outputs: ${identicalOutputs}/${results.length}`);
  console.log(`Average Similarity: ${(averageSimilarity * 100).toFixed(1)}%`);
  console.log(`\nExecution Time:`);
  console.log(`  Static:  ${avgStaticTime.toFixed(0)}ms`);
  console.log(`  Dynamic: ${avgDynamicTime.toFixed(0)}ms`);
  console.log(`  Difference: ${percentDifference > 0 ? '+' : ''}${percentDifference.toFixed(1)}%`);
  console.log(`\nRecommendation: ${recommendation}`);

  if (notes.length > 0) {
    console.log('\nNotes:');
    notes.forEach(note => console.log(`  • ${note}`));
  }

  console.log('\n' + '='.repeat(80) + '\n');

  // Save report
  const reportPath = path.join(
    process.cwd(),
    'migration-reports',
    'comparisons',
    `${flowName}-comparison.json`
  );
  const reportDir = path.dirname(reportPath);
  if (!fs.existsSync(reportDir)) {
    fs.mkdirSync(reportDir, { recursive: true });
  }
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
  console.log(`📄 Report saved: ${reportPath}\n`);

  return report;
}

// Main execution
async function main() {
  const args = process.argv.slice(2);
  const flowName = args[0];
  const runsArg = args.find(arg => arg.startsWith('--runs='));
  const numRuns = runsArg ? parseInt(runsArg.split('=')[1]) : 3;

  if (!flowName) {
    console.error('❌ Error: Flow name is required');
    console.log('\nUsage: tsx scripts/migration/compare-outputs.ts <flowName> [--runs=5]');
    process.exit(1);
  }

  console.log('🔍 Output Comparison Tool\n');
  console.log(`Flow: ${flowName}`);
  console.log(`Runs per test: ${numRuns}\n`);

  try {
    const report = await compareFlow(flowName, numRuns);

    if (report.recommendation === 'FAIL') {
      console.log('❌ Comparison FAILED - migration needs review');
      process.exit(1);
    } else if (report.recommendation === 'REVIEW') {
      console.log('⚠️  Comparison needs REVIEW - manual inspection recommended');
      process.exit(0);
    } else {
      console.log('✅ Comparison PASSED - migration successful!');
      process.exit(0);
    }

  } catch (error) {
    console.error('\n❌ Comparison failed:', error);
    process.exit(1);
  }
}

main();
"}

{"file_path": "scripts/migration/benchmark-flow.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Flow Benchmark Tool
 * 
 * Measures performance characteristics of static vs dynamic flows:
 * - Execution time
 * - Memory usage
 * - Throughput
 * - Latency percentiles
 * 
 * Usage:
 *   npm run benchmark-flow
 *   tsx scripts/migration/benchmark-flow.ts <flowName> [--iterations=100]
 */

import * as fs from 'fs';
import * as path from 'path';

interface BenchmarkMetrics {
  executionTimes: number[];
  memoryUsage: {
    heapUsed: number;
    heapTotal: number;
    external: number;
  }[];
  errors: number;
  successful: number;
}

interface BenchmarkResult {
  flowName: string;
  mode: 'static' | 'dynamic';
  iterations: number;
  timestamp: string;
  metrics: BenchmarkMetrics;
  statistics: {
    mean: number;
    median: number;
    min: number;
    max: number;
    p50: number;
    p95: number;
    p99: number;
    stdDev: number;
  };
  memoryStats: {
    avgHeapUsed: number;
    avgHeapTotal: number;
    maxHeapUsed: number;
  };
  throughput: number; // requests per second
}

interface ComparisonReport {
  flowName: string;
  timestamp: string;
  iterations: number;
  staticResult: BenchmarkResult;
  dynamicResult: BenchmarkResult;
  comparison: {
    speedDifference: number; // percentage
    memoryDifference: number; // percentage
    throughputDifference: number; // percentage
    recommendation: 'BETTER' | 'ACCEPTABLE' | 'WORSE';
    issues: string[];
  };
}

/**
 * Calculate statistics from execution times
 */
function calculateStatistics(times: number[]): BenchmarkResult['statistics'] {
  const sorted = [...times].sort((a, b) => a - b);
  const mean = sorted.reduce((sum, t) => sum + t, 0) / sorted.length;

  const median = sorted.length % 2 === 0
    ? (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
    : sorted[Math.floor(sorted.length / 2)];

  const min = sorted[0];
  const max = sorted[sorted.length - 1];

  const p50 = sorted[Math.floor(sorted.length * 0.50)];
  const p95 = sorted[Math.floor(sorted.length * 0.95)];
  const p99 = sorted[Math.floor(sorted.length * 0.99)];

  // Standard deviation
  const squareDiffs = sorted.map(t => Math.pow(t - mean, 2));
  const avgSquareDiff = squareDiffs.reduce((sum, d) => sum + d, 0) / sorted.length;
  const stdDev = Math.sqrt(avgSquareDiff);

  return { mean, median, min, max, p50, p95, p99, stdDev };
}

/**
 * Execute flow and measure performance
 */
async function executeWithMetrics(
  flowName: string,
  mode: 'static' | 'dynamic',
  input: any
): Promise<{ duration: number; memory: NodeJS.MemoryUsage; success: boolean }> {
  // Force garbage collection if available
  if (global.gc) {
    global.gc();
  }

  const memoryBefore = process.memoryUsage();
  const startTime = Date.now();

  try {
    if (mode === 'static') {
      const flowModule = await import(`@/ai/flows/${flowName}`);
      const flowFunction = Object.values(flowModule)[0] as any;
      await flowFunction(input);
    } else {
      const { executeDynamicFlow } = await import('@/ai/flows/dynamic-flow-executor');
      await executeDynamicFlow(flowName, input);
    }

    const duration = Date.now() - startTime;
    const memoryAfter = process.memoryUsage();

    return {
      duration,
      memory: {
        rss: memoryAfter.rss - memoryBefore.rss,
        heapTotal: memoryAfter.heapTotal - memoryBefore.heapTotal,
        heapUsed: memoryAfter.heapUsed - memoryBefore.heapUsed,
        external: memoryAfter.external - memoryBefore.external,
        arrayBuffers: 0,
      },
      success: true,
    };
  } catch (error) {
    const duration = Date.now() - startTime;
    return {
      duration,
      memory: process.memoryUsage(),
      success: false,
    };
  }
}

/**
 * Run benchmark for a flow
 */
async function benchmarkFlow(
  flowName: string,
  mode: 'static' | 'dynamic',
  iterations: number,
  testInput: any
): Promise<BenchmarkResult> {
  console.log(`\n🔄 Benchmarking ${mode} flow: ${flowName}`);
  console.log(`   Iterations: ${iterations}\n`);

  const metrics: BenchmarkMetrics = {
    executionTimes: [],
    memoryUsage: [],
    errors: 0,
    successful: 0,
  };

  const progressInterval = Math.max(1, Math.floor(iterations / 10));

  for (let i = 0; i < iterations; i++) {
    if ((i + 1) % progressInterval === 0) {
      const percent = ((i + 1) / iterations * 100).toFixed(0);
      process.stdout.write(`\r   Progress: ${percent}% (${i + 1}/${iterations})`);
    }

    const result = await executeWithMetrics(flowName, mode, testInput);

    if (result.success) {
      metrics.executionTimes.push(result.duration);
      metrics.memoryUsage.push({
        heapUsed: result.memory.heapUsed,
        heapTotal: result.memory.heapTotal,
        external: result.memory.external,
      });
      metrics.successful++;
    } else {
      metrics.errors++;
    }

    // Small delay to prevent overwhelming the system
    await new Promise(resolve => setTimeout(resolve, 10));
  }

  console.log('\r   Progress: 100% ✅\n');

  // Calculate statistics
  const statistics = calculateStatistics(metrics.executionTimes);

  const avgHeapUsed = metrics.memoryUsage.reduce((sum, m) => sum + m.heapUsed, 0) / metrics.memoryUsage.length;
  const avgHeapTotal = metrics.memoryUsage.reduce((sum, m) => sum + m.heapTotal, 0) / metrics.memoryUsage.length;
  const maxHeapUsed = Math.max(...metrics.memoryUsage.map(m => m.heapUsed));

  const totalTime = metrics.executionTimes.reduce((sum, t) => sum + t, 0);
  const throughput = (metrics.successful / (totalTime / 1000));

  return {
    flowName,
    mode,
    iterations,
    timestamp: new Date().toISOString(),
    metrics,
    statistics,
    memoryStats: {
      avgHeapUsed,
      avgHeapTotal,
      maxHeapUsed,
    },
    throughput,
  };
}

/**
 * Print benchmark result
 */
function printBenchmarkResult(result: BenchmarkResult): void {
  console.log(`📊 ${result.mode.toUpperCase()} Results:`);
  console.log(`   Success Rate: ${(result.metrics.successful / result.iterations * 100).toFixed(1)}%`);
  console.log(`\n   Execution Time:`);
  console.log(`     Mean:   ${result.statistics.mean.toFixed(2)}ms`);
  console.log(`     Median: ${result.statistics.median.toFixed(2)}ms`);
  console.log(`     Min:    ${result.statistics.min.toFixed(2)}ms`);
  console.log(`     Max:    ${result.statistics.max.toFixed(2)}ms`);
  console.log(`     P95:    ${result.statistics.p95.toFixed(2)}ms`);
  console.log(`     P99:    ${result.statistics.p99.toFixed(2)}ms`);
  console.log(`     StdDev: ${result.statistics.stdDev.toFixed(2)}ms`);
  console.log(`\n   Memory:`);
  console.log(`     Avg Heap: ${(result.memoryStats.avgHeapUsed / 1024 / 1024).toFixed(2)} MB`);
  console.log(`     Max Heap: ${(result.memoryStats.maxHeapUsed / 1024 / 1024).toFixed(2)} MB`);
  console.log(`\n   Throughput: ${result.throughput.toFixed(2)} req/sec\n`);
}

/**
 * Compare benchmark results
 */
function compareResults(staticResult: BenchmarkResult, dynamicResult: BenchmarkResult): ComparisonReport['comparison'] {
  const speedDifference = ((dynamicResult.statistics.mean - staticResult.statistics.mean) / staticResult.statistics.mean) * 100;
  const memoryDifference = ((dynamicResult.memoryStats.avgHeapUsed - staticResult.memoryStats.avgHeapUsed) / staticResult.memoryStats.avgHeapUsed) * 100;
  const throughputDifference = ((dynamicResult.throughput - staticResult.throughput) / staticResult.throughput) * 100;

  const issues: string[] = [];
  let recommendation: 'BETTER' | 'ACCEPTABLE' | 'WORSE' = 'ACCEPTABLE';

  // Speed analysis
  if (speedDifference > 50) {
    issues.push(`Dynamic flow is ${speedDifference.toFixed(1)}% slower`);
    recommendation = 'WORSE';
  } else if (speedDifference > 20) {
    issues.push(`Dynamic flow is ${speedDifference.toFixed(1)}% slower`);
    if (recommendation === 'ACCEPTABLE') recommendation = 'ACCEPTABLE';
  } else if (speedDifference < -10) {
    issues.push(`Dynamic flow is ${Math.abs(speedDifference).toFixed(1)}% faster!`);
    recommendation = 'BETTER';
  }

  // Memory analysis
  if (memoryDifference > 100) {
    issues.push(`Dynamic flow uses ${memoryDifference.toFixed(1)}% more memory`);
    if (recommendation !== 'WORSE') recommendation = 'WORSE';
  } else if (memoryDifference > 50) {
    issues.push(`Dynamic flow uses ${memoryDifference.toFixed(1)}% more memory`);
  }

  // Success rate
  const staticSuccessRate = (staticResult.metrics.successful / staticResult.iterations) * 100;
  const dynamicSuccessRate = (dynamicResult.metrics.successful / dynamicResult.iterations) * 100;

  if (dynamicSuccessRate < staticSuccessRate - 5) {
    issues.push(`Lower success rate: ${dynamicSuccessRate.toFixed(1)}% vs ${staticSuccessRate.toFixed(1)}%`);
    recommendation = 'WORSE';
  }

  return {
    speedDifference,
    memoryDifference,
    throughputDifference,
    recommendation,
    issues,
  };
}

/**
 * Generate test input for flow
 */
function generateTestInput(flowName: string): any {
  // Simple test inputs - can be customized per flow
  const inputs: Record<string, any> = {
    'generate-text': { prompt: 'Write a test sentence', language: 'en' },
    'paraphrase-text': { text: 'This is a test sentence.', style: 'formal' },
    'summarize-text': { text: 'This is a longer text that needs to be summarized for testing purposes.', maxLength: 50 },
    'translate-text': { text: 'Hello world', targetLanguage: 'es' },
  };

  return inputs[flowName] || { input: 'test input' };
}

/**
 * Main benchmark function
 */
async function main() {
  const args = process.argv.slice(2);
  const flowName = args[0];
  const iterationsArg = args.find(arg => arg.startsWith('--iterations='));
  const iterations = iterationsArg ? parseInt(iterationsArg.split('=')[1]) : 100;

  if (!flowName) {
    console.error('❌ Error: Flow name is required');
    console.log('\nUsage: tsx scripts/migration/benchmark-flow.ts <flowName> [--iterations=100]');
    process.exit(1);
  }

  console.log('⚡ Flow Benchmark Tool\n');
  console.log(`Flow: ${flowName}`);
  console.log(`Iterations: ${iterations}\n`);
  console.log('='.repeat(80));

  const testInput = generateTestInput(flowName);

  try {
    // Benchmark static flow
    const staticResult = await benchmarkFlow(flowName, 'static', iterations, testInput);
    printBenchmarkResult(staticResult);

    // Benchmark dynamic flow
    const dynamicResult = await benchmarkFlow(flowName, 'dynamic', iterations, testInput);
    printBenchmarkResult(dynamicResult);

    // Compare results
    const comparison = compareResults(staticResult, dynamicResult);

    console.log('='.repeat(80));
    console.log('📊 COMPARISON\n');
    console.log(`Speed:      ${comparison.speedDifference > 0 ? '+' : ''}${comparison.speedDifference.toFixed(1)}%`);
    console.log(`Memory:     ${comparison.memoryDifference > 0 ? '+' : ''}${comparison.memoryDifference.toFixed(1)}%`);
    console.log(`Throughput: ${comparison.throughputDifference > 0 ? '+' : ''}${comparison.throughputDifference.toFixed(1)}%`);
    console.log(`\nRecommendation: ${comparison.recommendation}`);

    if (comparison.issues.length > 0) {
      console.log('\nIssues:');
      comparison.issues.forEach(issue => console.log(`  • ${issue}`));
    }
    console.log('\n' + '='.repeat(80));

    // Save report
    const report: ComparisonReport = {
      flowName,
      timestamp: new Date().toISOString(),
      iterations,
      staticResult,
      dynamicResult,
      comparison,
    };

    const reportPath = path.join(
      process.cwd(),
      'migration-reports',
      'benchmarks',
      `${flowName}-benchmark.json`
    );
    const reportDir = path.dirname(reportPath);
    if (!fs.existsSync(reportDir)) {
      fs.mkdirSync(reportDir, { recursive: true });
    }
    fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
    console.log(`\n📄 Report saved: ${reportPath}\n`);

    if (comparison.recommendation === 'WORSE') {
      console.log('❌ Performance is significantly worse - optimization needed');
      process.exit(1);
    } else {
      console.log('✅ Performance is acceptable');
      process.exit(0);
    }

  } catch (error) {
    console.error('\n❌ Benchmark failed:', error);
    process.exit(1);
  }
}

main();
"}

{"file_path": "scripts/migration/rollback-migration.ts", "initial_content": "#!/usr/bin/env tsx
/**
 * Migration Rollback Tool
 * 
 * Safely rollback flow migrations by:
 * - Disabling dynamic flow configs
 * - Re-enabling static flows
 * - Preserving migration data for analysis
 * 
 * Usage:
 *   npm run rollback-migration
 *   tsx scripts/migration/rollback-migration.ts [flowName] [--hard]
 */

import * as fs from 'fs';
import * as path from 'path';
import { initializeApp } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';

// Initialize Firebase
try {
  initializeApp();
} catch (error) {
  // Already initialized
}

const db = getFirestore();

interface RollbackResult {
  flowName: string;
  success: boolean;
  action: 'soft-rollback' | 'hard-rollback' | 'restored';
  backupPath?: string;
  error?: string;
}

interface RollbackReport {
  timestamp: string;
  type: 'soft' | 'hard';
  totalFlows: number;
  successful: number;
  failed: number;
  results: RollbackResult[];
}

/**
 * Soft rollback - disable dynamic flow but keep config
 */
async function softRollback(flowName: string): Promise<RollbackResult> {
  console.log(`\n🔄 Soft rollback: ${flowName}`);

  try {
    // Find the flow config
    const configsRef = db.collection('flowConfigs');
    const snapshot = await configsRef.where('name', '==', flowName).get();

    if (snapshot.empty) {
      throw new Error(`Flow config not found: ${flowName}`);
    }

    const doc = snapshot.docs[0];
    const currentConfig = doc.data();

    // Create backup
    const backupPath = path.join(
      process.cwd(),
      'migration-backups',
      'rollbacks',
      `${flowName}_${Date.now()}.json`
    );
    const backupDir = path.dirname(backupPath);
    if (!fs.existsSync(backupDir)) {
      fs.mkdirSync(backupDir, { recursive: true });
    }
    fs.writeFileSync(backupPath, JSON.stringify(currentConfig, null, 2));
    console.log(`  💾 Backup saved: ${backupPath}`);

    // Disable the flow
    await doc.ref.update({
      isActive: false,
      rollbackDate: new Date().toISOString(),
      rollbackReason: 'Manual rollback via script',
    });

    console.log(`  ✅ Flow disabled (config preserved)`);

    return {
      flowName,
      success: true,
      action: 'soft-rollback',
      backupPath,
    };

  } catch (error) {
    console.error(`  ❌ Failed:`, error);
    return {
      flowName,
      success: false,
      action: 'soft-rollback',
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * Hard rollback - delete dynamic flow config completely
 */
async function hardRollback(flowName: string): Promise<RollbackResult> {
  console.log(`\n🗑️  Hard rollback: ${flowName}`);

  try {
    // Find the flow config
    const configsRef = db.collection('flowConfigs');
    const snapshot = await configsRef.where('name', '==', flowName).get();

    if (snapshot.empty) {
      throw new Error(`Flow config not found: ${flowName}`);
    }

    const doc = snapshot.docs[0];
    const currentConfig = doc.data();

    // Create backup
    const backupPath = path.join(
      process.cwd(),
      'migration-backups',
      'hard-rollbacks',
      `${flowName}_${Date.now()}.json`
    );
    const backupDir = path.dirname(backupPath);
    if (!fs.existsSync(backupDir)) {
      fs.mkdirSync(backupDir, { recursive: true });
    }
    fs.writeFileSync(backupPath, JSON.stringify(currentConfig, null, 2));
    console.log(`  💾 Backup saved: ${backupPath}`);

    // Delete the config
    await doc.ref.delete();

    console.log(`  ✅ Flow config deleted`);

    return {
      flowName,
      success: true,
      action: 'hard-rollback',
      backupPath,
    };

  } catch (error) {
    console.error(`  ❌ Failed:`, error);
    return {
      flowName,
      success: false,
      action: 'hard-rollback',
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * Restore a flow from backup
 */
async function restoreFromBackup(backupPath: string): Promise<RollbackResult> {
  console.log(`\n♻️  Restoring from backup: ${backupPath}`);

  try {
    if (!fs.existsSync(backupPath)) {
      throw new Error(`Backup file not found: ${backupPath}`);
    }

    const backupData = JSON.parse(fs.readFileSync(backupPath, 'utf-8'));
    const flowName = backupData.name;

    // Check if flow already exists
    const configsRef = db.collection('flowConfigs');
    const snapshot = await configsRef.where('name', '==', flowName).get();

    if (!snapshot.empty) {
      console.log(`  ⚠️  Flow config already exists, updating...`);
      await snapshot.docs[0].ref.set({
        ...backupData,
        restoredAt: new Date().toISOString(),
        restoredFrom: backupPath,
      });
    } else {
      console.log(`  ✨ Creating new flow config...`);
      await configsRef.add({
        ...backupData,
        restoredAt: new Date().toISOString(),
        restoredFrom: backupPath,
      });
    }

    console.log(`  ✅ Flow restored successfully`);

    return {
      flowName,
      success: true,
      action: 'restored',
      backupPath,
    };

  } catch (error) {
    console.error(`  ❌ Failed:`, error);
    return {
      flowName: 'unknown',
      success: false,
      action: 'restored',
      backupPath,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * List all migrated flows
 */
async function listMigratedFlows(): Promise<string[]> {
  const configsRef = db.collection('flowConfigs');
  const snapshot = await configsRef.get();

  return snapshot.docs.map(doc => doc.data().name as string);
}

/**
 * Rollback all flows
 */
async function rollbackAll(type: 'soft' | 'hard'): Promise<RollbackReport> {
  console.log(`\n${'='.repeat(80)}`);
  console.log(`🔄 Rolling back ALL flows (${type} rollback)`);
  console.log('='.repeat(80));

  const flows = await listMigratedFlows();
  console.log(`\n📋 Found ${flows.length} migrated flows\n`);

  const report: RollbackReport = {
    timestamp: new Date().toISOString(),
    type,
    totalFlows: flows.length,
    successful: 0,
    failed: 0,
    results: [],
  };

  for (const flowName of flows) {
    const result = type === 'soft' 
      ? await softRollback(flowName)
      : await hardRollback(flowName);

    report.results.push(result);

    if (result.success) {
      report.successful++;
    } else {
      report.failed++;
    }
  }

  return report;
}

/**
 * Print rollback report
 */
function printReport(report: RollbackReport): void {
  console.log('\n' + '='.repeat(80));
  console.log('📊 ROLLBACK SUMMARY');
  console.log('='.repeat(80));
  console.log(`\nType: ${report.type.toUpperCase()} rollback`);
  console.log(`Total flows: ${report.totalFlows}`);
  console.log(`✅ Successful: ${report.successful}`);
  console.log(`❌ Failed: ${report.failed}`);
  console.log(`📈 Success rate: ${((report.successful / report.totalFlows) * 100).toFixed(1)}%`);

  if (report.failed > 0) {
    console.log('\nFailed rollbacks:');
    report.results
      .filter(r => !r.success)
      .forEach(r => console.log(`  ❌ ${r.flowName}: ${r.error}`));
  }

  console.log('\n' + '='.repeat(80) + '\n');

  // Save report
  const reportPath = path.join(
    process.cwd(),
    'migration-reports',
    'rollbacks',
    `rollback-${Date.now()}.json`
  );
  const reportDir = path.dirname(reportPath);
  if (!fs.existsSync(reportDir)) {
    fs.mkdirSync(reportDir, { recursive: true });
  }
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
  console.log(`📄 Report saved: ${reportPath}\n`);
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2);
  const flowName = args.find(arg => !arg.startsWith('--'));
  const isHard = args.includes('--hard');
  const restoreArg = args.find(arg => arg.startsWith('--restore='));
  const listOnly = args.includes('--list');

  console.log('🔄 Migration Rollback Tool\n');

  try {
    if (listOnly) {
      // Just list migrated flows
      const flows = await listMigratedFlows();
      console.log(`📋 Migrated flows (${flows.length}):\n`);
      flows.forEach(flow => console.log(`  • ${flow}`));
      console.log('');

    } else if (restoreArg) {
      // Restore from backup
      const backupPath = restoreArg.split('=')[1];
      const result = await restoreFromBackup(backupPath);

      if (result.success) {
        console.log('\n✅ Restore successful!');
      } else {
        console.log('\n❌ Restore failed!');
        process.exit(1);
      }

    } else if (flowName) {
      // Rollback specific flow
      const result = isHard 
        ? await hardRollback(flowName)
        : await softRollback(flowName);

      if (result.success) {
        console.log(`\n✅ ${flowName} rolled back successfully!`);
      } else {
        console.log(`\n❌ Rollback failed!`);
        process.exit(1);
      }

    } else {
      // Rollback all flows
      console.log('⚠️  WARNING: This will rollback ALL migrated flows!');
      console.log(`   Type: ${isHard ? 'HARD (delete configs)' : 'SOFT (disable configs)'}`);
      console.log('\n   Press Ctrl+C to cancel, or wait 5 seconds to continue...\n');

      await new Promise(resolve => setTimeout(resolve, 5000));

      const report = await rollbackAll(isHard ? 'hard' : 'soft');
      printReport(report);

      if (report.failed > 0) {
        console.log('⚠️  Some rollbacks failed - check the report for details');
        process.exit(1);
      } else {
        console.log('✅ All flows rolled back successfully!');
      }
    }

    process.exit(0);

  } catch (error) {
    console.error('\n❌ Rollback failed:', error);
    process.exit(1);
  }
}

main();
"}

